function businessEntrance(lang){const t=refinedContact[lang];return `<section class="business-entrance" aria-label="Cheers Experiences"><div class="wrap entrance-grid"><a href="#hotel" class="entrance-path"><span class="eyebrow">01 / ${premiumLabels[lang].hotels}</span><h2>${t.hotels}</h2><p>${t.hotelDesc}</p><span class="entrance-link">${t.hotelExplore}</span></a><a href="eventos.html?lang=${lang}" class="entrance-path"><span class="eyebrow">02 / ${premiumLabels[lang].events}</span><h2>${t.events}</h2><p>${t.eventDesc}</p><span class="entrance-link">${t.eventExplore}</span></a></div></section>`;}
